fn RG_RG_010(x: f64, z: f64, NF: f64) -> f64 {
    let mut res: f64 = 0.0;
    let tiny: f64 = 1e-4;
    let tinyinv: f64 = 1.0 / tiny;

    let u: f64 = x + z;
    let v: f64 = x - z;

    // x=z
    if (v.abs() <= tiny && u >= 2.0 - tiny) || (v.abs() <= tiny && u <= tiny) {
        return 0.0;
    }

    // intersection region of x=z and x=1-z:
    if v.abs() < 0.99 * tiny && (u - 1.0).abs() < 0.99 * tiny {
        let u0: f64 = 1.0 - tiny;
        let v0: f64 = -tiny;
        let u1: f64 = 1.0 - tiny;
        let v1: f64 = tiny;
        let u2: f64 = 1.0 + tiny;
        let v2: f64 = -tiny;

        let x0: f64 = 0.5 * (u0 + v0);
        let z0: f64 = 0.5 * (u0 - v0);
        let x1: f64 = 0.5 * (u1 + v1);
        let z1: f64 = 0.5 * (u1 - v1);
        let x2: f64 = 0.5 * (u2 + v2);
        let z2: f64 = 0.5 * (u2 - v2);

        let pt0: f64 = RG_RG_010(x0, z0, NF);
        let pt1: f64 = RG_RG_010(x1, z1, NF);
        let pt2: f64 = RG_RG_010(x2, z2, NF);

        res = pt0 + 0.5 * (pt1 - pt0) * tinyinv * (v - v0) + 0.5 * (pt2 - pt0) * tinyinv * (u - u0);
        return res;
    }
    if v.abs() < 0.99 * tiny {
        let v0: f64 = -tiny;
        let v1: f64 = tiny;

        let x0: f64 = 0.5 * (u + v0);
        let z0: f64 = 0.5 * (u - v0);
        let x1: f64 = 0.5 * (u + v1);
        let z1: f64 = 0.5 * (u - v1);

        let pt0: f64 = RG_RG_010(x0, z0, NF);
        let pt1: f64 = RG_RG_010(x1, z1, NF);
        res = pt0 + 0.5 * (pt1 - pt0) * tinyinv * (v - v0);
        return res;
    }

    // x=1-z
    if (u - 1.0).abs() <= tiny && v <= tiny - 1.0 {
        res = 0.0;
        return res;
    }
    if (u - 1.0).abs() <= tiny && v >= 1.0 - tiny {
        res = 0.0;
        return res;
    }
    if (u - 1.0).abs() < 0.99 * tiny {
        let u0: f64 = 1.0 - tiny;
        let u1: f64 = 1.0 + tiny;

        let x0: f64 = 0.5 * (u0 + v);
        let z0: f64 = 0.5 * (u0 - v);
        let x1: f64 = 0.5 * (u1 + v);
        let z1: f64 = 0.5 * (u1 - v);

        let pt0: f64 = RG_RG_010(x0, z0, NF);
        let pt1: f64 = RG_RG_010(x1, z1, NF);
        res = pt0 + 0.5 * (pt1 - pt0) * tinyinv * (u - u0);
        return res;
    }

    if z != x && z != 1. - x {
        let tmp: f64 = 2. / 3. * lmuf * (1.0 / x) * (1.0 / z) * (1.0 / NQCD) + (- 2. / 3. * lmuf * (1.0 / x) * (1.0 / z) * NQCD) + (- 4. / 3. * lmuf * (1.0 / x) * (1.0 / NQCD)) + 4. / 3. * lmuf * (1.0 / x) * NQCD + 1. / 2. * lmuf * (1.0 / z) * (1.0 / NQCD) + (- 1. / 2. * lmuf * (1.0 / z) * NQCD) + (- lmuf * (1.0 / NQCD)) + lmuf * NQCD + (- 1. / 2. * lmuf * x * (1.0 / z) * (1.0 / NQCD)) + 1. / 2. * lmuf * x * (1.0 / z) * NQCD + lmuf * x * (1.0 / NQCD) + (- lmuf * x * NQCD) + (- 2. / 3. * lmuf * (x * x) * (1.0 / z) * (1.0 / NQCD)) + 2. / 3. * lmuf * (x * x) * (1.0 / z) * NQCD + 4. / 3. * lmuf * (x * x) * (1.0 / NQCD) + (- 4. / 3. * lmuf * (x * x) * NQCD) + ln(x) * lmuf * (1.0 / z) * (1.0 / NQCD) + (- ln(x) * lmuf * (1.0 / z) * NQCD) + (- 2.0 * ln(x) * lmuf * (1.0 / NQCD)) + 2.0 * ln(x) * lmuf * NQCD + ln(x) * lmuf * x * (1.0 / z) * (1.0 / NQCD) + (- ln(x) * lmuf * x * (1.0 / z) * NQCD) + (- 2.0 * ln(x) * lmuf * x * (1.0 / NQCD)) + 2.0 * ln(x) * lmuf * x * NQCD;
        res += tmp;
    }

    return res;
}

